$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest

function Invoke-NativeChecked {
    param([scriptblock]$Command, [string]$Name)
    & $Command
    if ($LASTEXITCODE -ne 0) { throw "$Name failed with exit code $LASTEXITCODE" }
}

$repo = (Resolve-Path (Join-Path $PSScriptRoot '..')).Path
$temp = Join-Path ([System.IO.Path]::GetTempPath()) ("ji-stage4-standalone-" + [guid]::NewGuid().ToString('N'))
try {
    Invoke-NativeChecked { & (Join-Path $repo 'gradlew.bat') ':ji-standalone:runtimeZip' '--offline' '--rerun-tasks' } 'standalone archive build'
    $archive = Get-ChildItem (Join-Path $repo 'ji-java/products/ji-standalone/build/distributions') -Filter '*-java21.zip' | Select-Object -First 1
    if ($null -eq $archive) { throw 'standalone Java 21 archive was not produced' }
    Expand-Archive -LiteralPath $archive.FullName -DestinationPath $temp
    $root = Get-ChildItem $temp -Directory | Select-Object -First 1
    if ($null -eq $root) { throw 'standalone archive has no root directory' }
    $launcher = Join-Path $root.FullName 'bin/ji-host.bat'
    $bundledJava = Join-Path $root.FullName 'runtime/bin/java.exe'
    if (-not (Test-Path $launcher) -or -not (Test-Path $bundledJava)) { throw 'standalone archive is missing launcher or bundled Java 21 runtime' }
    $env:PATH = 'C:\Windows\System32'
    Remove-Item Env:JAVA_HOME -ErrorAction SilentlyContinue
    Invoke-NativeChecked { & $bundledJava '-version' } 'bundled Java runtime'
    $launcherText = [System.IO.File]::ReadAllText($launcher)
    if ($launcherText -match '(?i)node|pnpm|vite') { throw 'standalone launcher has a Node runtime dependency' }
    Write-Output 'STAGE4_STANDALONE_CLEAN_UNPACK_OK'
} finally {
    Remove-Item -LiteralPath $temp -Recurse -Force -ErrorAction SilentlyContinue
}
